INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT147-S4-Q13$batch10$, 147, 4, 13, $batch10$Principle-Conform$batch10$, $batch10$While playing a game with a ball, both Emma and John carelessly ignored the danger their game posed to nearby objects. An errant throw by John struck and broke a neighbor’s window. Because his throw broke the window, John, but not Emma, should be required to perform chores for the neighbor as compensation for the damage.$batch10$, $batch10$Which one of the following conforms most closely to the principle illustrated above?$batch10$, $batch10$C$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=147 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$While looking after her neighbor’s pets, Laura left the door to her neighbor’s house unlocked. Fortunately, nothing bad happened as a result. But her neighbor should not trust Laura to look after her pets in the future.$batch10$, $batch10$No Damage$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$Gerald hired Linda and Seung to move his furniture to a new residence. Linda and Seung carefully followed Gerald’s instructions, but not all of the furniture fit in the moving truck. Gerald should still be required to pay Linda and Seung for the work they did.$batch10$, $batch10$No Fault$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$Terry and Chris were racing their cars on a public street. Chris lost control of his car and struck a parked car. Chris, but not Terry, should be required to pay to repair the damage.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$Alexis and Juan rented a boat for the afternoon. Because of improper use by the previous renter, the boat’s engine malfunctioned during their excursion. The boat’s owner should be required to refund Alexis’s and Juan’s rental fees.$batch10$, $batch10$Wrong Party$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$Susan and Leland disregarded posted warnings in order to skate on a frozen pond. When the ice broke, Susan’s ankle was injured. Susan cannot hold the pond’s owners responsible for her injuries.$batch10$, $batch10$Different Question$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Situation$batch10$, $batch10$Emma and John were both careless while playing ball. Only John's throw broke the window, so only John should have to make it up to the neighbor.$batch10$), (1, $batch10$Evaluate$batch10$, $batch10$Both were equally careless, so carelessness alone doesn't decide who pays. What decides it is who actually caused the damage. The principle: when two people share the carelessness, the one whose action caused the damage should compensate, and the other shouldn't.$batch10$), (2, $batch10$Goal$batch10$, $batch10$Two people are both careless, only one causes the damage, and only that one has to pay.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$Only one person is involved, and nothing bad happened. The principle is about assigning the cost of actual damage between two careless people.$batch10$), ($batch10$B$batch10$, $batch10$Linda and Seung were careful, and nothing was damaged. This is about paying for work, not compensating for harm.$batch10$), ($batch10$C$batch10$, $batch10$Terry and Chris were both racing on a public street, so both were careless. Chris alone hit the parked car, and Chris alone pays. That matches John and Emma exactly.$batch10$), ($batch10$D$batch10$, $batch10$Alexis and Juan didn't cause the problem, and the one who did isn't the one paying. The owner refunds them for damage done by someone else.$batch10$), ($batch10$E$batch10$, $batch10$This is about whether the careless person can make the owner pay. In the stimulus, one of the careless people pays the neighbor.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT147-S4-Q13$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
